"""Controller consensus projection.

On an advancing step the controller sees V = alpha*X + (1-alpha)*z0 + u0 on the
live edges and solves

    route:  min_{h>=0, z<=h}    h      + 0.5*rho*sum (z-V)^2
    admit:  min_{h=1,   z<=1}          0.5*rho*sum (z-V)^2

z is unbounded below, so for a fixed ceiling z = min(V, h) and the route case
reduces to a one-dimensional water-filling on the positive part of V.
"""
import math

import numpy as np


def controller_solve(rho, V, mode):
    """Return (h, z, t) for the live-edge values ``V``."""
    V = np.asarray(V, dtype=float)
    r = float(rho)
    if mode == "admit":
        h = 1.0
        z = np.minimum(V, h)
        t = r * (V - z)
        return h, z, t
    if V.size == 0:
        return 0.0, V.copy(), V.copy() * 0.0
    pos = np.sort(V[V > 0.0])[::-1]
    if pos.size == 0:
        h = 0.0
    elif r * float(pos.sum()) <= 1.0:
        h = 0.0
    else:
        target = 1.0 / r
        csum = np.cumsum(pos)
        kk = np.arange(1, pos.size + 1, dtype=float)
        levels = (csum - target) / kk
        active = 0
        for i in range(pos.size):
            if pos[i] > levels[i]:
                active = i + 1
            else:
                break
        h = float(levels[active - 1])
        if h < 0.0:
            h = 0.0
    z = np.minimum(V, h)
    t = r * (V - z)
    if h > 0.0:
        # Tighten the pressure so that the live complementarity product
        # h*(1-sum t) vanishes to summation noise: the water level is a
        # rounded double, which otherwise leaves a residual of order
        # rho*k*ulp(h) in sum t.
        idx = int(np.argmax(t)) if t.size else -1
        if idx >= 0 and t[idx] > 0.0:
            others = math.fsum(float(v) for i, v in enumerate(t) if i != idx)
            newval = 1.0 - others
            delta = newval - float(t[idx])
            if abs(delta) <= 1e-6 and newval >= 0.0:
                t[idx] = newval
    return h, z, t


